        'fails_at': int(row['fails at']) if row['fails at'] != '-' else None,
        'returns_at': int(row['returns at']) if row['returns at'] != '-' else None
    }

machine_ids = sorted(machines.keys())

# Queue at time t (before scheduling round)
# Task info lookup
def get_task_info(task_id):
    return submissions[task_id]

# Machine capacity
def get_free(machine_id):
    return machines[machine_id]['CPU'], machines[machine_id]['memory']

# Simulation state
class Sim:
    def __init__(self):
        self.up = {m: True for m in machine_ids}
        self.used_cpu = {m: 0 for m in machine_ids}
        self.used_mem = {m: 0 for m in machine_ids}
        self.running = {m: [] for m in machine_ids}  # list of (task_id, start_time, finish_time)
        self.queue = []  # task_ids waiting
        self.evictions = defaultdict(int)
        self.first_starts = {}  # task_id -> first start time

    def free_cpu(self, m):
        return machines[m]['CPU'] - self.used_cpu[m]

    def free_mem(self, m):
        return machines[m]['memory'] - self.used_mem[m]

    def can_fit(self, task_id, m):
        if not self.up[m]:
            return False
        info = get_task_info(task_id)
        return self.free_cpu(m) >= info['CPU'] and self.free_mem(m) >= info['memory']

    def start_task(self, task_id, m):
        info = get_task_info(task_id)
        self.used_cpu[m] += info['CPU']
        self.used_mem[m] += info['memory']
        finish_time = sim.current_time + info['run_time']
        self.running[m].append((task_id, sim.current_time, finish_time))
        if task_id not in self.first_starts:
            self.first_starts[task_id] = sim.current_time

    def stop_task(self, task_id):
        """Remove task from running on its machine"""
        for m in machine_ids:
            self.running[m] = [(t, s, f) for t, s, f in self.running[m] if t != task_id]
        info = get_task_info(task_id)
        # Find which machine it was on
        for m in machine_ids:
            if (m, task_id) in [(m2, t) for m2 in machine_ids for t, s, f in self.running[m2]]:
                self.used_cpu[m] -= info['CPU']
                self.used_mem[m] -= info['memory']
                return m
        return None

    def stop_task_from_machine(self, task_id, m):
        """Remove task from specific machine"""
        info = get_task_info(task_id)
        self.running[m] = [(t, s, f) for t, s, f in self.running[m] if t != task_id]
        self.used_cpu[m] -= info['CPU']
        self.used_mem[m] -= info['memory']

