def simulate_state(stop_time):
    """Simulate the cluster state up to stop_time (exclusive of scheduling at stop_time)"""
    machine_state = {m: {} for m in machine_ids}

    sorted_times = sorted(events_by_time.keys())

    for t in sorted_times:
        if t == stop_time:
            break

        events = events_by_time[t]

        for e in events:
            event_type = e['event']
            task_id = e['task']
            machine = e['machine']

            if event_type == 'finish':
                if machine in machine_state and task_id in machine_state[machine]:
                    del machine_state[machine][task_id]

            elif event_type == 'fail':
                if machine in machine_state and task_id in machine_state[machine]:
                    del machine_state[machine][task_id]

            elif event_type == 'start':
                if machine in machine_state:
                    machine_state[machine][task_id] = {
                        'cpu': e['CPU'],
                        'mem': e['memory'],
                        'finish_time': t + e['run time'],
                        'priority': e['priority'],
                        'started': t
                    }

            elif event_type == 'evict':
                if machine in machine_state and task_id in machine_state[machine]:
                    del machine_state[machine][task_id]

    return machine_state

